            foreach (['src', 'tests', 'config', 'database', 'routes'] as $scope) {
120→                expect(implode("\n", $violations))->toContain($temporary.'/'.$package.'/'.$scope.'/unused-import.php:1: retired configuration helper');
            }
        }
