        })->toThrow(RuntimeException::class, 'published v0.2 fixture must match pinned SHA-256');
        expect(file_exists($executed))->toBeFalse();
    } finally {
        unlink($temporary);
        if (file_exists($executed)) {
            unlink($executed);
        }
    }
